const axios = require('axios');
const item = $input.first().json;
const summary = (item.summary || '').toString();
const title = (item.title !== undefined && item.title !== null) ? item.title.toString() : null;

let ollamaModel = 'qwen3.5:27b-q4_K_M'; try { ollamaModel = $env.OLLAMA_MODEL_DMS || 'qwen3:14b'; } catch(e) {}
let threshold = 0.3; try { const t = parseFloat($env.DMS_LANGUAGE_HEURISTIC_THRESHOLD); if (!isNaN(t)) threshold = t; } catch(e) {}

// Lightweight local heuristic: ratio of common-English words to total words.
// No external API, no extra model — a local wordlist check per PROJ-79 technical requirements.
const ENGLISH_MARKERS = new Set(['the','and','of','to','in','for','is','on','with','as','by','at','from','this','that','was','were','are','be','been','has','have','had','it','an','a','or','not','but','which','their','its','if','you','your','we','our','will','would','can','could','should','about','into','than','then','they','he','she','his','her','them','also','all','any','other','more','most','such','no','only','so','when','what','who','how','where']);
function englishRatio(text) {
  const words = (text || '').toLowerCase().match(/[a-zäöüß]+/g) || [];
  if (words.length < 6) return null; // too short / name-only — inconclusive, never flagged
  let hits = 0;
  for (const w of words) if (ENGLISH_MARKERS.has(w)) hits++;
  return hits / words.length;
}

function looksEnglish(text) {
  const ratio = englishRatio(text);
  if (ratio === null) return false; // inconclusive -> not a hit, avoids false alarms on short/neutral text
  return ratio >= threshold;
}

const summaryFlag = looksEnglish(summary);
const titleFlag = title !== null ? looksEnglish(title) : false;
const suspectedEnglish = summaryFlag || titleFlag;

if (!suspectedEnglish) {
  return [{ json: { summary, title, languageUncertain: false, language_retried: false, extracted: null } }];
}

// 2nd attempt: same extraction prompt, but with an explicit, stricter German directive appended.
const basePrompt = item.extraction_prompt || '';
const strictPrompt = basePrompt + '\n\nIMPORTANT: Write ALL text field values (summary, title, and any other free-text field) exclusively in German. Do NOT use English, even if the source document is in English. This is a strict requirement — translate the content into German for your response.';

let retried = false;
let finalSummary = summary;
let finalTitle = title;
let finalExtracted = null;
try {
  const resp = await axios.post('http://ollama-3090:11434/api/generate', {
    model: ollamaModel,
    prompt: strictPrompt,
    stream: false,
    format: 'json',
    options: { temperature: 0 }
  }, { timeout: 300000 });
  const parsed = JSON.parse(resp.data.response || '{}');
  retried = true;
  finalExtracted = parsed;
  if (typeof parsed.summary === 'string' && parsed.summary.trim()) finalSummary = parsed.summary;
  if (title !== null && typeof parsed.title === 'string' && parsed.title.trim()) finalTitle = parsed.title;
} catch(e) {
  // 2nd attempt failed outright — keep the 1st attempt's values, still flagged uncertain below
  retried = true;
}

const stillUncertain = looksEnglish(finalSummary) || (finalTitle !== null && looksEnglish(finalTitle));

const result = { summary: finalSummary, title: finalTitle, languageUncertain: stillUncertain, language_retried: retried, extracted: finalExtracted };
return [{ json: result }];
